<?php require __DIR__.'/_guard.php';
$total=(int)$conn->query("SELECT COUNT(*) n FROM products")->fetch_assoc()['n'];
$units=(int)$conn->query("SELECT COALESCE(SUM(quantity),0) n FROM products")->fetch_assoc()['n'];
$low=(int)$conn->query("SELECT COUNT(*) n FROM products WHERE quantity <= reorder_level")->fetch_assoc()['n'];
$recent=$conn->query("SELECT h.*,p.product_name FROM stock_history h JOIN products p ON p.id=h.product_id ORDER BY h.id DESC LIMIT 8");
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Storekeeper | FreshMart</title><link rel="stylesheet" href="../assets/css/modern.css"></head><body><main class="page"><header class="topbar"><div><a class="brand" href="dashboard.php">Fresh<span>Mart</span></a><h1>Storekeeper workspace</h1><p class="muted">Welcome, <?=htmlspecialchars($_SESSION['full_name']??'Storekeeper')?>. Manage daily inventory operations.</p></div><a class="btn" href="../logout.php">Sign out</a></header><nav class="nav"><a href="dashboard.php">Overview</a><a href="stock.php">Stock In / Out</a><a href="history.php">Stock history</a><a href="low_stock.php">Low stock</a><a href="profile.php">My Account</a></nav><section class="grid"><article class="panel stat"><span>Products</span><strong><?=$total?></strong></article><article class="panel stat"><span>Total units in store</span><strong><?=$units?></strong></article><article class="panel stat"><span>Low-stock products</span><strong><?=$low?></strong></article></section><section class="panel"><h2>Recent stock activity</h2><div class="table-wrap"><table><thead><tr><th>Product</th><th>Action</th><th>Qty</th><th>Before</th><th>After</th><th>Date</th></tr></thead><tbody><?php if($recent && $recent->num_rows): while($r=$recent->fetch_assoc()): ?><tr><td><?=htmlspecialchars($r['product_name'])?></td><td><span class="badge"><?=strtoupper($r['action'])?></span></td><td><?=$r['quantity']?></td><td><?=$r['previous_quantity']?></td><td><?=$r['new_quantity']?></td><td><?=htmlspecialchars($r['created_at'])?></td></tr><?php endwhile; else: ?><tr><td colspan="6">No stock activity recorded yet.</td></tr><?php endif;?></tbody></table></div></section></main><a href="profile.php" class="btn" style="position:fixed;right:20px;bottom:20px;z-index:50">My Account</a></body></html>
